# calls (outside the repo): str, strip, any, startswith, endswith, lstrip
# doc: Return True if path points to a sensitive file (secrets, keys, credentials).
def _is_secret_path(path: str) -> bool:
    """Return True if path points to a sensitive file (secrets, keys, credentials)."""
    if not path:
        return False
    p = str(path).replace("\\", "/").lower()
    parts = p.strip("/").split("/")
    if any(part in SECRET_DIR_NAMES for part in parts[:-1]):
        return True
    name = parts[-1]
    if not name:
        return False
