# calls (outside the repo): split, set, enumerate, match, index, range, len, strip, lstrip, add, group
# doc: Keys passed via `with:` to every `uses: ./` step in a workflow.
def _uses_local_with(text):
    """Keys passed via `with:` to every `uses: ./` step in a workflow."""
    lines = text.split("\n")
    keys = set()
    for i, line in enumerate(lines):
        if not re.match(r"^\s*(?:- )?uses:\s*\./\s*(?:#.*)?$", line):
            continue
        col = line.index("uses:")
        for j in range(i + 1, len(lines)):
            nxt = lines[j]
            if not nxt.strip():
                continue
            indent = len(nxt) - len(nxt.lstrip())
            if indent < col or (indent == col and not nxt.lstrip().startswith("with:")):
                break
            if indent == col:
                continue
            m = re.match(r"^\s+([A-Za-z][\w-]*):", nxt)
            if m:
                keys.add(m.group(1))
    return keys

